@@ -0,0 +1,80 @@
+export function buildUtmUrl(input, campaign) {
+  const url = new URL(input);
+
+  if (typeof input !== 'string' || !input.startsWith('http://') && !input.startsWith('https://')) {
+    throw new RangeError('Input must be an absolute http/https string');
+  }
+
+  if (typeof campaign !== 'object' || campaign === null) {
+    throw new RangeError('Campaign must be a plain object');
+  }
+
+  const requiredParams = ['utm_source', 'utm_medium', 'utm_campaign'];
+  const optionalParams = ['utm_term', 'utm_content'];
+  const validKeys = new Set([...requiredParams, ...optionalParams]);
+
+  for (const key of Object.keys(campaign)) {
+    if (!validKeys.has(key)) {
+      throw new RangeError(`Unknown campaign key: ${key}`);
+    }
+  }
+
+  const params = {};
+
+  for (const [key, value] of Object.entries(campaign)) {
+    if (typeof value !== 'string') {
+      throw new RangeError(`Value for ${key} must be a string`);
+    }
+
+    const trimmedValue = value.trim();
+
+    if (requiredParams.includes(key)) {
+      if (trimmedValue === '') {
+        throw new RangeError(`Required parameter ${key} cannot be blank`);
+      }
+      params[key] = trimmedValue;
+    } else {
+      if (trimmedValue !== '') {
+        params[key] = trimmedValue;
+      }
+    }
+  }
+
+  const existingParams = new Map();
+  for (const [key, value] of url.searchParams) {
+    if (key.startsWith('utm_')) {
+      existingParams.set(key, value);
+    } else {
+      existingParams.set(key, value);
+    }
+  }
+
+  const finalParams = new Map();
+
+  for (const [key, value] of url.searchParams) {
+    if (!key.startsWith('utm_')) {
+      finalParams.set(key, value);
+    } else {
+      existingParams.set(key, value);
+    }
+  }
+
+  for (const [key, value] of params) {
+    finalParams.set(key, value);
+  }
+
+  const sortedParams = Array.from(finalParams.entries()).sort((a, b) => {
+    if (a[0] < b[0]) return -1;
+    if (a[0] > b[0]) return 1;
+    return a[1].localeCompare(b[1]);
+  });
+
+  const query = sortedParams.map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`).join('&');
+
+  let canonicalUrl = url.origin + url.pathname;
+  if (query) {
+    canonicalUrl += '?' + query;
+  }
+
+  return canonicalUrl;
+}

